from collections import deque

def transform(grid):
    H,W=len(grid),len(grid[0]); ones={(r,c) for r in range(H) for c in range(W) if grid[r][c]==1}
    # exterior background cells under 4-connectivity
    zeros={(r,c) for r in range(H) for c in range(W) if grid[r][c]==0}
    ext=set(); q=deque()
    for r,c in zeros:
        if r in (0,H-1) or c in (0,W-1): ext.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            p=(r+dr,c+dc)
            if p in zeros and p not in ext: ext.add(p); q.append(p)
    interior=zeros-ext
    # label components of ones, identify if neighboring (8?) to interior region
    # Color 3 inner one-cell halo, 2 exterior 8-halo only for ones adjacent to internal zero
    out=[row[:] for row in grid]
    for r,c in interior:
        if any((r+dr,c+dc) in ones for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc): out[r][c]=3
    # components 4-connected, flag if adjacent to interior cavity
    seen=set()
    for p in ones:
        if p in seen: continue
        comp={p}; seen.add(p); qq=[p]
        while qq:
            r,c=qq.pop()
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                z=(r+dr,c+dc)
                if z in ones and z not in seen: seen.add(z);comp.add(z);qq.append(z)
        if any((r+dr,c+dc) in interior for r,c in comp for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc):
            for r,c in comp:
                for dr in (-1,0,1):
                    for dc in (-1,0,1):
                        z=(r+dr,c+dc)
                        if z in ext: out[z[0]][z[1]]=2
    return out

